package android.database.sqlite;import android.content.*;import android.database.*;import java.util.*;public class SQLiteDatabase{final List<ContentValues> rows=new ArrayList<>();public void execSQL(String query){}public Cursor query(String table,String[] columns,String where,String[] args,String group,String having,String order){return query(table,columns,where,args,group,having,order,null);}public Cursor query(String table,String[] columns,String where,String[] args,String group,String having,String order,String limit){List<Object[]> found=new ArrayList<>();for(ContentValues row:rows){if(!Objects.equals(row.get("url"),args[0])||args.length>1&&!Objects.equals(row.get("body"),args[1]))continue;Object[] value=new Object[columns.length];for(int i=0;i<columns.length;i++)value[i]=row.get(columns[i]);found.add(value);}if(order!=null&&order.contains("DESC"))Collections.reverse(found);return new Cursor(found);}public long insertOrThrow(String table,String nullColumn,ContentValues values){ContentValues copy=new ContentValues();copy.putAll(values);copy.put("id",rows.size()+1L);rows.add(copy);return rows.size();}public int delete(String table,String where,String[] args){int n=rows.size();rows.clear();return n;}}
